from az_lib import *
# ---- 6 Azure Files and Blob Storage
C(6,"Azure file share basics?","Fully managed **SMB** (port 445) or **NFS** (premium only) shares. Set a **quota** (size). Mount from Windows, Linux or macOS. **Azure File Sync** caches shares on Windows Servers.")
C(6,"Azure File Sync parts?","**Storage Sync Service** → **sync group** → one **cloud endpoint** (the Azure file share) + **server endpoints** (folders on registered servers). **Cloud tiering** keeps hot files local and leaves cold files as pointers.")
C(6,"Share snapshots and soft delete for Azure Files?","**Share snapshots:** read-only, point-in-time copies of the **whole share**; restore single files from them. **Soft delete:** keeps a **deleted share** for **1-365 days** so you can undelete it. Deleting a share deletes its snapshots too.")
C(6,"Blob container access levels?","**Private** (no anonymous access), **Blob** (anonymous read of blobs only), **Container** (anonymous read and list). Anonymous access must also be **allowed at the account level**, which is off by default for new accounts.")
C(6,"Access tiers and minimum days?","**Hot** (frequent access), **Cool** (30 days), **Cold** (90 days), **Archive** (180 days, **offline**). Deleting or moving earlier than the minimum charges an **early deletion** fee. Hot or Cool can be the account default; Archive is set **per blob**.")
C(6,"How do you read an archived blob?","**Rehydrate** it: change its tier to Hot, Cool or Cold, or **copy** it to an online tier. **Standard priority** can take up to **15 hours**; **High priority** usually under **1 hour**.")
C(6,"Blob lifecycle management?","Rules (JSON) per account that **move blobs to cooler tiers** or **delete** them after N days since **last modification**, **creation** or **last access** (needs access tracking). Filter by **prefix** or blob index tag. Also manages **versions** and **snapshots**. Runs about once a day.")
C(6,"Blob versioning vs blob soft delete vs snapshots?","**Versioning:** every overwrite keeps the **previous version** automatically. **Soft delete:** deleted blobs are kept for a retention period (1-365 days). **Snapshots:** read-only copies you take **by hand**. **Point-in-time restore** needs versioning, change feed and soft delete.")
C(6,"Immutable blob storage?","WORM: **time-based retention** (cannot modify or delete for N days) and **legal hold** (until cleared). Set at container or version level. For regulatory records.")
Q(6,"Blobs are rarely read after 30 days and never after 180 days, but must be kept for 7 years. You need to minimize cost automatically. What should you configure?","A lifecycle management rule that moves blobs to Cool, then Archive",["Blob versioning","A stored access policy","Object replication"],"Lifecycle rules tier and delete blobs by age automatically.")
Q(6,"A user needs to read an archived blob within one hour. What should you do?","Change the blob tier to Hot with high rehydration priority",["Read the blob directly from the Archive tier","Enable soft delete","Create a snapshot of the blob"],"Archive is offline. High priority rehydration usually completes in under an hour.")
Q(6,"Users accidentally overwrite important blobs. You need to restore the previous content automatically kept on each write. What should you enable?","Blob versioning",["Container soft delete","A lifecycle management rule","Anonymous read access"],"Versioning keeps the previous version on every write. Soft delete protects against deletes.")
Q(6,"Which TWO features let you recover a deleted Azure file share or a file in it?",["Soft delete for file shares","Share snapshots"],["Blob versioning","Object replication"],"Share soft delete restores the share. Snapshots restore earlier versions of files.")
YN(6,["Archive tier can be set as the default access tier of a storage account.","Moving a blob out of Cool after 10 days can incur an early deletion charge.","Point-in-time restore for block blobs requires versioning, change feed and soft delete."],[0,1,1],"Archive is per blob only. Cool has a 30-day minimum. PITR needs all three.")
M(6,"Match each requirement to the feature.",[("Keep files local on a branch office server","Azure File Sync"),("Restore a folder from yesterday's share copy","Share snapshot"),("Lock records so no one can delete them for 7 years","Immutable storage"),("Delete logs older than 90 days","Lifecycle management")],"Each feature has one job.")
Q(6,"You set a container's access level to Blob, but anonymous users still get an error. What is the likely cause?","Anonymous access is disallowed on the storage account",["The blobs are in the Hot tier","Soft delete is enabled","The container has a stored access policy"],"Allow Blob anonymous access must be enabled on the account before container-level public access works.")
Q(6,"Which access tier has a 180-day minimum and is offline?","Archive",["Cold","Cool","Hot"],"Archive is the cheapest storage, 180-day minimum, and must be rehydrated before reading.")
D(6,"Share snapshot","Share soft delete","Brings back a file share that was deleted.",1,"Soft delete restores deleted shares. Snapshots restore earlier file versions.")
D(6,"Blob versioning","Blob snapshot","Created automatically every time a blob is overwritten.",0,"Snapshots are manual.")
D(6,"Cool tier","Archive tier","Must be rehydrated before reading.",1,"Archive is offline.")
D(6,"Lifecycle management","Object replication","Moves blobs to a cheaper tier after 60 days.",0,"Lifecycle rules tier and delete. Object replication copies between accounts.")
# ---- 7 ARM templates and Bicep
C(7,"Sections of an ARM template?","**$schema**, **contentVersion**, **parameters** (values at deploy time), **variables** (computed values), **functions**, **resources** (required), **outputs** (values returned).")
C(7,"Bicep file building blocks?","`param` (inputs), `var` (computed values), `resource` (symbolic name + type@apiVersion), `module` (another Bicep file), `output`. Bicep **compiles to an ARM JSON template**; no state file.")
C(7,"Convert between Bicep and ARM JSON?","`az bicep build` turns **Bicep into JSON**. `az bicep decompile` turns **JSON into Bicep** (best effort, review the result).")
C(7,"How do you export a template from what already exists?","Resource group or resource → **Export template** (current state), or **Deployments** history → a deployment's template (what was deployed). Exports may need cleanup and parameterizing.")
C(7,"Incremental vs Complete deployment mode?","**Incremental (default):** adds and updates resources in the template, **leaves others alone**. **Complete:** also **deletes** resources in the resource group that are **not in the template**. Use **what-if** to preview.")
C(7,"Commands to deploy a template to a resource group?","CLI: `az deployment group create -g RG1 --template-file main.bicep --parameters @params.json`. PowerShell: `New-AzResourceGroupDeployment`. Other scopes: `az deployment sub/mg/tenant create`.")
C(7,"What does dependsOn do?","Makes Resource Manager deploy one resource **after** another (for example a NIC before the VM). Bicep usually adds it **automatically** when you reference another resource's symbolic name.")
C(7,"Common template functions?","`resourceGroup().location`, `uniqueString()` (deterministic hash for unique names), `concat()` / string interpolation in Bicep, `resourceId()`, `parameters()` and `variables()` in JSON.")
C(7,"Parameter file and secure parameters?","A **parameters file** (`.parameters.json` or `.bicepparam`) supplies values per environment. Mark passwords `securestring` / `@secure()` and pull them from **Key Vault** with a reference, not plain text.")
Q(7,"You have an ARM template in JSON and want to maintain it in Bicep. Which command should you run?","az bicep decompile",["az bicep build","az deployment group what-if","az group export"],"Decompile converts JSON to Bicep. Build does the reverse.")
Q(7,"You deploy a template to RG1 in Complete mode. RG1 contains a VM that is not in the template. What happens to the VM?","It is deleted",["It is left unchanged","It is stopped","The deployment fails"],"Complete mode removes resources in the group that the template does not define.")
Q(7,"Which section of an ARM template is required in every template?","resources",["parameters","outputs","variables"],"Only $schema, contentVersion and resources are required.")
Q(7,"You need to preview which resources a deployment will create, change or delete without deploying. What should you run?","A what-if operation",["Export template","az bicep build","A Complete mode deployment"],"What-if shows the predicted changes before you deploy.")
Q(7,"Which TWO ways give you a template for resources that already exist in a resource group?",["Export template from the resource group","Open the template from the resource group's deployment history"],["az bicep build","Azure Advisor"],"Export captures current state. Deployment history shows what was deployed.")
YN(7,["Incremental is the default deployment mode.","Bicep needs a state file to track deployed resources, like Terraform.","A parameter marked @secure() is not written to the deployment history."],[1,0,1],"Incremental is default. Bicep has no state file. Secure parameter values are not logged.")
M(7,"Match each template part to its job.",[("Values supplied at deployment time","parameters"),("Values computed inside the template","variables"),("The things to create","resources"),("Values returned after deployment","outputs")],"Inputs, internals, resources, results.")
Q(7,"A template creates a storage account and needs a globally unique name that stays the same on every redeploy to the same resource group. Which function should you use?","uniqueString(resourceGroup().id)",["newGuid()","utcNow()","rand()"],"uniqueString is deterministic for the same input. newGuid changes every time.")
Q(7,"A Bicep file deploys a VM that references a NIC by its symbolic name. Do you need to add dependsOn?","No, Bicep adds the dependency from the reference",["Yes, Bicep never infers dependencies","Yes, but only in Complete mode","No, because NICs are deployed last"],"Referencing another resource's symbolic name creates an implicit dependency.")
D(7,"Incremental mode","Complete mode","Deletes resources not in the template.",1,"Complete removes extras. Incremental leaves them.")
D(7,"az bicep build","az bicep decompile","Turns ARM JSON into Bicep.",1,"Decompile = JSON to Bicep.")
D(7,"parameters","variables","Values computed inside the template, not supplied by the user.",1,"Variables are internal.")
D(7,"Export template","Deployment history","Shows the exact template that was used in an earlier deployment.",1,"Export shows current state, not the original template.")
# ---- 8 Virtual machines
C(8,"VM size families to recognize?","**B** burstable (cheap, low steady use), **D** general purpose, **E** memory optimized, **F** compute optimized, **L** storage optimized, **N** GPU, **M** very large memory.")
C(8,"Resizing a VM?","Pick a new size; the VM **restarts**. If the size is **not available** on the current hardware cluster, you must **deallocate (stop)** the VM first to see and choose it.")
C(8,"VM disk roles?","**OS disk** (boot, persistent), **temporary disk** (local, **data lost** on deallocate, redeploy or host move; D: on Windows), **data disks** (persistent, attach several).")
C(8,"Managed disk types, fast to slow?","**Ultra Disk** and **Premium SSD v2** (data disks only, adjustable IOPS), **Premium SSD** (production), **Standard SSD** (light use), **Standard HDD** (backup, dev). You can **grow** a disk but **not shrink** it.")
C(8,"Availability set facts?","Spreads VMs across **fault domains** (shared power and network, **max 3**) and **update domains** (rebooted together, **max 20**, default 5). Set at VM creation. **99.95%** SLA for 2+ VMs. Protects against rack failure, not datacenter failure.")
C(8,"Availability zones?","Separate datacenters with independent power, cooling and network in one region. VMs in **2+ zones** get a **99.99%** SLA. You cannot use an availability set and a zone for the same VM.")
C(8,"VM Scale Sets: Flexible vs Uniform?","**Flexible (recommended):** mix VM sizes, up to 1000 VMs, full VM control, spread across zones and fault domains. **Uniform:** identical VMs from one model. Orchestration mode is **fixed at creation**.")
C(8,"Scale set autoscale settings?","**Minimum, maximum and default** instance counts. **Scale-out** and **scale-in** rules on metrics (for example CPU over 70% for 10 min), a **cooldown**, or schedules. **Scale-in policy** decides which VM is removed first.")
C(8,"Disk encryption options for VMs?","**Server-side encryption** is always on. **Encryption at host** also encrypts temp disks and caches end to end; **use it for new VMs**. **Azure Disk Encryption** (BitLocker/DM-Crypt with Key Vault) is **retiring on 15 Sept 2028**; migrate to encryption at host.")
C(8,"Moving a VM?","**Another resource group or subscription:** Move (with its disks, NIC, IP and other dependencies); the VM's **resource ID changes**, its region does not. **Another region:** **Azure Resource Mover** (uses Site Recovery replication) or Site Recovery directly.")
Q(8,"You try to resize VM1 but the size you need does not appear in the list. What should you do first?","Stop (deallocate) VM1",["Detach the data disks","Delete the OS disk","Move VM1 to another resource group"],"Sizes not available on the current cluster appear after the VM is deallocated.")
Q(8,"An app stores data on the D: drive of a Windows VM. After maintenance the data is gone. Why?","D: is the temporary disk, which is not persistent",["The OS disk was reimaged","The data disk was Standard HDD","The VM was in an availability set"],"Temporary disks are lost on deallocation, redeploy or host move.")
Q(8,"You need the highest SLA for two VMs running the same app in one region. How should you deploy them?","In two different availability zones",["In the same availability set","In the same fault domain","On one dedicated host"],"Zones give 99.99%. Availability sets give 99.95%.")
Q(8,"You are deploying new VMs that must have encrypted temp disks and caches. Azure Disk Encryption is retiring. What should you enable?","Encryption at host",["Infrastructure encryption on a storage account","Storage Service Encryption only","A stored access policy"],"Encryption at host covers temp disks and caches and replaces ADE.")
Q(8,"You need to move a VM from West Europe to North Europe. Which service should you use?","Azure Resource Mover",["Move to another resource group","Azure Migrate app containerization","Azure Advisor"],"Moving between resource groups or subscriptions keeps the region. Resource Mover moves across regions.")
Q(8,"Which TWO statements about availability sets are true?",["They spread VMs across up to 3 fault domains","A VM must be added to the set when it is created"],["They protect against a full datacenter failure","They give a 99.99% SLA"],"Availability sets protect within a datacenter (99.95%). Zones protect against datacenter loss (99.99%).")
YN(8,["You can reduce the size of a managed disk from 256 GiB to 128 GiB.","Ultra Disks can be used as OS disks.","Moving a VM to another resource group changes its resource ID."],[0,0,1],"Disks can only grow. Ultra Disks are data disks only. The resource ID includes the resource group.")
M(8,"Match each workload to the VM family.",[("Web server that idles most of the day","B-series"),("In-memory database cache","E-series"),("Batch math with high CPU","F-series"),("Machine learning training on GPUs","N-series")],"B burst, E memory, F compute, N GPU.")
Q(8,"A scale set must add VMs when average CPU is above 75% and remove them below 25%, never going under 2 VMs. What should you configure?","Autoscale with scale-out and scale-in rules and a minimum of 2",["A larger VM size","Manual scale with 2 instances","An availability set with 2 fault domains"],"Metric rules with min/max counts automate scaling.")
D(8,"Availability set","Availability zone","Protects against a whole datacenter failing.",1,"Zones are separate datacenters.")
D(8,"Fault domain","Update domain","VMs rebooted together during planned maintenance.",1,"Update domains group maintenance reboots.")
D(8,"Flexible scale set","Uniform scale set","Can mix different VM sizes.",0,"Flexible orchestration allows mixed sizes.")
D(8,"Azure Disk Encryption","Encryption at host","The recommended choice for new VMs.",1,"ADE is retiring in 2028.")
# ---- 9 Containers
C(9,"Azure Container Registry SKUs?","**Basic** (learning, small), **Standard** (more storage and throughput), **Premium** (adds **geo-replication**, **private endpoints**, content trust, more throughput). All are private registries.")
C(9,"How should apps pull images from ACR?","With a **managed identity** or service principal that has the **AcrPull** role. The **admin user** is **disabled by default** and is for testing only.")
C(9,"Build an image in Azure without Docker locally?","`az acr build --registry myreg --image app:v1 .` uses **ACR Tasks** to build in the cloud and push to the registry.")
C(9,"Azure Container Instances (ACI)?","Run containers **without managing servers or orchestration**. Billed per second. Good for simple apps, tasks and burst jobs. A **container group** is containers that share host, network, storage and lifecycle (like a pod). Multi-container groups are **Linux only**.")
C(9,"ACI sizing and scaling?","Set **CPU and memory** per container at deploy time; to change them you **redeploy**. ACI has **no built-in autoscale**: run more container groups yourself. Restart policy: **Always, OnFailure, Never**.")
C(9,"Azure Container Apps?","Serverless containers for microservices and APIs on a managed Kubernetes base. **KEDA** autoscaling (HTTP, TCP, CPU, memory, queues and events), **scale to zero**, **revisions** with traffic splitting, ingress, Dapr. You don't manage the cluster.")
C(9,"Container Apps scale settings?","**Min and max replicas** per revision. **HTTP rule:** add a replica when concurrent requests per replica pass the threshold (default 10). Min replicas 0 = **scale to zero** (no usage charge while idle). **Vertical scaling is not supported.**")
C(9,"Container Apps revisions?","A revision is an **immutable snapshot** of the app. Changing **scale rules** or the container creates a new revision. In **multiple revision mode** you split traffic between revisions (blue-green, canary).")
C(9,"ACI vs Container Apps vs AKS?","**ACI:** one-off or simple containers, no autoscale. **Container Apps:** serverless microservices with autoscale and scale to zero. **AKS:** full Kubernetes control, you manage more.")
Q(9,"You need an Azure Container Registry with replicas in three regions and access only over private endpoints. Which SKU is required?","Premium",["Basic","Standard","Any SKU with the admin user enabled"],"Geo-replication and private endpoints are Premium features.")
Q(9,"A containerized API must scale to zero when idle and scale out based on HTTP traffic. What should you use?","Azure Container Apps",["Azure Container Instances","An Azure VM with Docker","Azure Container Registry"],"Container Apps uses KEDA to scale on HTTP requests and supports scale to zero.")
Q(9,"A container in ACI needs more memory. What must you do?","Redeploy the container group with the new memory setting",["Enable autoscale on the container group","Add a scale rule","Resize the underlying VM"],"ACI resources are set at deployment. Change them by redeploying.")
Q(9,"An AKS cluster must pull images from ACR without storing passwords. What should you grant?","The AcrPull role to the cluster's managed identity",["Enable the ACR admin user","Make the registry public","The Owner role on the subscription"],"Use identity plus AcrPull, not admin credentials.")
Q(9,"Which TWO are true about an ACI container group?",["Containers in it share a lifecycle and network","Multi-container groups are supported on Linux"],["It scales automatically on CPU","It must run on a VM you manage"],"A container group is like a pod. Multi-container groups are Linux only, and ACI has no autoscale.")
YN(9,["Changing a Container Apps scale rule creates a new revision.","Azure Container Apps supports vertical scaling of replicas.","The ACR admin user is enabled by default."],[1,0,0],"Scale changes create revisions. Container Apps scales out, not up. Admin user is off by default.")
M(9,"Match each scenario to the service.",[("Nightly batch job in one container, no servers","Azure Container Instances"),("Microservices that scale on queue length","Azure Container Apps"),("Store and version private images","Azure Container Registry"),("Full control of a Kubernetes cluster","Azure Kubernetes Service")],"Pick by how much you want to manage.")
Q(9,"You must build a container image from source code and push it to ACR, but the build machine has no Docker. What should you run?","az acr build",["az container create","docker push","az aks create"],"ACR Tasks build images in the cloud.")
Q(9,"A Container App has an HTTP rule with 50 concurrent requests and max replicas 5. Traffic is zero for an hour and min replicas is 0. How many replicas run?","0",["1","5","50"],"With min replicas 0, the app scales to zero when idle.")
D(9,"Azure Container Instances","Azure Container Apps","Scales to zero with KEDA rules.",1,"ACI has no autoscale.")
D(9,"Standard ACR","Premium ACR","Supports geo-replication.",1,"Premium only.")
D(9,"Admin user","Managed identity with AcrPull","Recommended way for apps to pull images.",1,"Admin user is for testing only.")
# ---- 10 Azure App Service
C(10,"What does an App Service plan define?","The **region**, **OS** (Windows or Linux), **pricing tier** (features) and **instance size and count**. **All apps in the plan share** those instances, and scale settings apply to **every app in the plan**.")
C(10,"App Service tiers in one line each?","**Free/Shared:** shared VMs, dev only. **Basic:** dedicated, manual scale, custom domains and TLS. **Standard:** autoscale, **deployment slots**, backups. **Premium v3:** more scale and power. **Isolated v2:** dedicated **network isolation** (App Service Environment).")
C(10,"Maximum instances by tier?","**Basic 3**, **Standard 10**, **Premium 30**, **Isolated 100**. Autoscale rules start at **Standard**.")
C(10,"Custom domain mapping?","Add a **CNAME** (subdomain) or **A record** (root) pointing to the app, plus a **TXT record `asuid`** to prove ownership. Needs a **paid tier** (not Free).")
C(10,"TLS certificates for App Service?","**App Service managed certificate** (free, auto-renew, **not wildcard**), import from **Key Vault**, or upload a **PFX**. Bind with **SNI SSL** or IP SSL. Turn on **HTTPS Only** and set **minimum TLS 1.2**. TLS binding needs **Basic or higher**.")
C(10,"App Service backup?","Backs up **app content, configuration and a linked database**. Custom backups need **Basic or higher**. **Basic:** production slot only. Standard and up: more slots and higher limits.")
C(10,"App Service networking: inbound vs outbound?","**Inbound:** **access restrictions** (allow/deny by IP, service tag, VNet) and **private endpoints** (private IP). **Outbound:** **VNet integration** lets the app reach resources in a VNet; **Hybrid Connections** reach on-premises endpoints.")
C(10,"Deployment slots?","Live apps with their own host names (staging, test) in **Standard or higher** (Standard has 5). **Swap** warms up the target instances first, so **no downtime**. **Swap back** to roll back. **Slot settings (sticky)** stay with the slot. Route a percentage of traffic to a slot to test in production.")
C(10,"Scale up vs scale out for App Service?","**Scale up:** bigger tier or instance size (more CPU, memory, features). **Scale out:** more instances, manual or **autoscale** rules (Standard+), or **automatic scaling** in Premium.")
Q(10,"You need to deploy a new version to a staging environment, test it, then move it to production with no downtime. What is the minimum tier?","Standard",["Basic","Free","Shared"],"Deployment slots start at Standard.")
Q(10,"An app in the Basic tier needs 6 instances. What should you do?","Scale up to Standard or higher",["Scale out to 6 instances","Add a deployment slot","Enable VNet integration"],"Basic allows at most 3 instances. Standard allows 10.")
Q(10,"You map www.contoso.com to an App Service app. Which TWO DNS records are needed?",["A CNAME record for www pointing to the app","A TXT record asuid.www with the verification ID"],["An MX record for www","A PTR record for the app's IP"],"Subdomains use CNAME plus the asuid TXT record for verification.")
Q(10,"An app must call a database on a private IP in VNet1. What should you configure on the app?","VNet integration",["A private endpoint","An access restriction","A deployment slot"],"VNet integration is for outbound traffic from the app into the VNet. Private endpoints are for inbound.")
Q(10,"You need a free TLS certificate for www.contoso.com that renews automatically. What should you use?","An App Service managed certificate",["A wildcard certificate from App Service","A self-signed certificate in the app settings","A Key Vault secret with a password"],"Managed certificates are free and auto-renew but are not wildcard.")
YN(10,["Autoscale rules are available in the Basic tier.","Slot settings marked as deployment slot settings move with the app during a swap.","Two apps in the same App Service plan share the same instances."],[0,0,1],"Autoscale starts at Standard. Sticky settings stay with the slot. Apps in a plan share compute.")
M(10,"Match each requirement to the App Service feature.",[("Allow traffic only from the office IP range","Access restrictions"),("App reaches a VM in a VNet","VNet integration"),("Users reach the app on a private IP","Private endpoint"),("Send 10% of users to the new version","Deployment slot traffic routing")],"Inbound vs outbound, and slots for testing.")
Q(10,"After a swap, the new production version has a bug. What is the fastest way to restore the previous version?","Swap the slots back",["Restore from backup","Redeploy from source control","Scale out the plan"],"The previous version is now in the staging slot, so swapping back restores it.")
Q(10,"You scale an App Service plan out to 4 instances. The plan hosts App1 and App2. How many instances does App2 run on?","4",["1","2","It depends on App2's own scale setting"],"Scale settings apply to all apps in the plan.")
D(10,"VNet integration","Private endpoint","Gives the app a private inbound IP address.",1,"Private endpoint is inbound. VNet integration is outbound.")
D(10,"Scale up","Scale out","Add more instances.",1,"Scale out adds instances. Scale up changes size or tier.")
D(10,"Basic tier","Standard tier","First tier with deployment slots.",1,"Slots start at Standard.")
D(10,"App Service managed certificate","Key Vault certificate","Supports a wildcard domain.",1,"Managed certificates are not wildcard.")
